Here is the complete `galaga.html`:

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>GALAGA</title>
<style>
  html,body{margin:0;padding:0;height:100%;background:#000;overflow:hidden}
  #wrap{position:fixed;inset:0;display:flex;align-items:center;justify-content:center}
  canvas{background:#000;image-rendering:pixelated;image-rendering:crisp-edges}
</style>
</head>
<body>
<div id="wrap"><canvas id="c" width="224" height="288"></canvas></div>
<script>
'use strict';
/* =========================================================================
   GALAGA (browser clone) - single file, no external resources.
   Sections: setup, audio, sprites, helpers, state, input, game flow,
             update logic, rendering, main loop.
   ========================================================================= */

/* ------------------------------- setup -------------------------------- */
const W = 224, H = 288;                       // arcade resolution (3:4)
const cv = document.getElementById('c'), ctx = cv.getContext('2d');
function resize(){
  const s = Math.max(1, Math.floor(Math.min(innerWidth / W, innerHeight / H)));
  cv.style.width  = (W * s) + 'px';
  cv.style.height = (H * s) + 'px';
}
addEventListener('resize', resize); resize();

/* ------------------------------- audio -------------------------------- */
let AC = null, master = null, noiseBuf = null, muted = false;
function initAudio(){
  if (AC) return;
  try {
    AC = new (window.AudioContext || window.webkitAudioContext)();
    master = AC.createGain(); master.gain.value = muted ? 0 : 0.22;
    master.connect(AC.destination);
    noiseBuf = AC.createBuffer(1, AC.sampleRate, AC.sampleRate);
    const d = noiseBuf.getChannelData(0);
    for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
  } catch(e){ AC = null; }
}
function tone(f0, f1, dur, type, vol, when){
  if (!AC) return;
  const t = AC.currentTime + (when || 0);
  const o = AC.createOscillator(), g = AC.createGain();
  o.type = type || 'square';
  o.frequency.setValueAtTime(Math.max(1, f0), t);
  o.frequency.exponentialRampToValueAtTime(Math.max(1, f1), t + dur);
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  o.connect(g); g.connect(master);
  o.start(t); o.stop(t + dur + 0.02);
}
function noise(dur, vol, f0, f1, when){
  if (!AC) return;
  const t = AC.currentTime + (when || 0);
  const s = AC.createBufferSource(); s.buffer = noiseBuf;
  const flt = AC.createBiquadFilter(); flt.type = 'bandpass';
  flt.frequency.setValueAtTime(f0, t);
  flt.frequency.exponentialRampToValueAtTime(Math.max(20, f1), t + dur);
  const g = AC.createGain();
  g.gain.setValueAtTime(vol, t);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  s.connect(flt); flt.connect(g); g.connect(master);
  s.start(t); s.stop(t + dur + 0.02);
}
function sfx(name){
  if (!AC) return;
  switch(name){
    case 'shot':      tone(1050, 220, 0.09, 'square', 0.35); break;
    case 'enemyDie':  noise(0.22, 0.9, 2600, 150); tone(300, 60, 0.2, 'triangle', 0.3); break;
    case 'bossHit':   noise(0.14, 0.9, 900, 200); tone(180, 90, 0.14, 'square', 0.3); break;
    case 'playerDie': noise(0.7, 1.0, 1800, 60); tone(320, 30, 0.7, 'sawtooth', 0.5);
                      noise(0.5, 0.6, 500, 40, 0.1); break;
    case 'beam':      tone(120, 420, 0.17, 'sawtooth', 0.14); break;
    case 'dock':      tone(520, 1040, 0.25, 'square', 0.3); break;
    case 'extra':     tone(660, 660, 0.1, 'square', 0.3); tone(880, 880, 0.15, 'square', 0.3, 0.1); break;
    case 'jingle': {  // short stage-start fanfare
      const n = [523, 523, 523, 392, 523, 659, 587, 523];
      const d = [0, .1, .2, .3, .45, .6, .78, .95];
      for (let i = 0; i < n.length; i++) tone(n[i], n[i], 0.11, 'square', 0.28, d[i]);
      break; }
  }
}
function toggleMute(){ muted = !muted; if (master) master.gain.value = muted ? 0 : 0.22; }

/* ------------------------------ sprites ------------------------------- */
/* Pixel-art sprites as string rows; each char maps to a palette colour. */
const SPR = {
  player: [[
    "......W......",
    "......W......",
    ".....WWW.....",
    ".....WRW.....",
    "W....WRW....W",
    "WW...WRW...WW",
    ".WWWRRRRRWWW.",
    "..WRRRRRRRW..",
    "...RRRRRRR...",
    "..BBRRRRRBB..",
    ".B..B.R.B..B.",
    "B...B.R.B...B"
  ]],
  zako: [
    [ "..B.....B..",
      "..BB...BB..",
      ".BBBB.BBBB.",
      ".BBYYYYYBB.",
      "YYBYYYYYBYY",
      "YY.YYYYY.YY",
      "...YYYYY...",
      "....YYY....",
      ".....Y....." ],
    [ ".....Y.....",
      "....YYY....",
      "...YYYYY...",
      "YY.YYYYY.YY",
      "YYBYYYYYBYY",
      ".BBYYYYYBB.",
      ".BBBB.BBBB.",
      "..BB...BB..",
      "..B.....B.." ]
  ],
  goei: [
    [ "RR.........RR",
      "RRR.......RRR",
      "RRRR.....RRRR",
      ".RRRR.R.RRRR.",
      ".RRRRRRRRRRR.",
      "..RRRRWRRRR..",
      "...RRRRRRR...",
      "..RR.RRR.RR..",
      ".R...RRR...R.",
      ".....RRR....." ],
    [ ".....RRR.....",
      "....RRRRR....",
      "...RRRRRRR...",
      "..RRRRRRRRR..",
      ".RRRRRWRRRRR.",
      ".RRRRRRRRRRR.",
      ".RRRRRRRRRRR.",
      "..RRRRRRRRR..",
      "...RR.R.RR...",
      ".....RRR....." ]
  ],
  boss: [
    [ "G.....G.....G",
      "GG...GGG...GG",
      ".GG.GGGGG.GG.",
      "..GGGGGGGGG..",
      ".GGGYGGGYGGG.",
      ".GGGGGGGGGGG.",
      "GGGGGGWGGGGGG",
      "GG.GGGGGGG.GG",
      "G..GGGGGGG..G",
      "...GG.G.GG...",
      "....GGGGG....",
      ".....GGG....." ],
    [ ".G...G.G...G.",
      "..G.GGG.G..G.",
      ".GG.GGGGG.GG.",
      "..GGGGGGGGG..",
      ".GGGYGGGYGGG.",
      ".GGGGGGGGGGG.",
      "GGGGGGWGGGGGG",
      "GG.GGGGGGG.GG",
      "G..GGGGGGG..G",
      "...GG.G.GG...",
      "....GGGGG....",
      ".....GGG....." ]
  ]
};
const PAL = {
  player:   { W:'#ffffff', R:'#ff2828', B:'#3858ff' },
  captured: { W:'#ff5050', R:'#e00000', B:'#ff3030' },
  zako:     { B:'#3868ff', Y:'#ffe020' },
  goei:     { R:'#ff3838', W:'#ffffff' },
  boss:     { G:'#28d028', W:'#ffffff', Y:'#ffff00' },
  bossHit:  { G:'#4848ff', W:'#ffffff', Y:'#ffff00' }
};
function drawSpr(rows, cx, cy, pal){
  const h = rows.length, w = rows[0].length;
  const x0 = Math.round(cx - w / 2), y0 = Math.round(cy - h / 2);
  for (let r = 0; r < h; r++){
    const line = rows[r];
    for (let c = 0; c < w; c++){
      const col = pal[line[c]];
      if (col){ ctx.fillStyle = col; ctx.fillRect(x0 + c, y0 + r, 1, 1); }
    }
  }
}

/* ------------------------------ helpers ------------------------------- */
const rnd  = (a, b) => a + Math.random() * (b - a);
const irnd = (a, b) => Math.floor(rnd(a, b + 1));
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
function catmull(pts, u){
  const n = pts.length - 1;
  let s = clamp(u, 0, 0.999999) * n, i = Math.floor(s), t = s - i;
  const p0 = pts[Math.max(0, i - 1)], p1 = pts[i],
        p2 = pts[Math.min(n, i + 1)], p3 = pts[Math.min(n, i + 2)];
  const t2 = t * t, t3 = t2 * t;
  const f = (a, b, c, d) =>
    0.5 * ((2 * b) + (c - a) * t + (2 * a - 5 * b + 4 * c - d) * t2 + (3 * a - 3 * c + d - b) * t3);
  return { x: f(p0.x, p1.x, p2.x, p3.x), y: f(p0.y, p1.y, p2.y, p3.y) };
}
function overlap(ax, ay, aw, ah, bx, by, bw, bh){
  return Math.abs(ax - bx) * 2 < aw + bw && Math.abs(ay - by) * 2 < ah + bh;
}
function T(str, x, y, col, sz, al){
  ctx.fillStyle = col || '#ffffff';
  ctx.font = 'bold ' + (sz || 8) + 'px monospace';
  ctx.textAlign = al || 'left';
  ctx.textBaseline = 'top';
  ctx.fillText(str, x, y);
}

/* ------------------------------- state -------------------------------- */
const game = {
  mode:'attract', t:0, paused:false, timer:0, msg:'',
  stage:1, score:0, hi:parseInt(localStorage.getItem('galagaHi') || '0', 10) || 0,
  nextExtra:20000, breathMix:0, diveTimer:3, diveAllow:0,
  shotsFired:0, shotsHit:0,
  challenge:null, captureBoss:null, captureT:0, captureFrom:null
};
const player = { x:112, alive:false, dual:false, lives:2, invuln:0 };
let enemies = [], pBullets = [], eBullets = [], explosions = [], freedShips = [];

/* entry-path groups: [startDelay, waypoints, enemies(startIdx, count)] */
const ENTRY = [
  { d:0.0,  path:[{x:-40,y:100},{x:30,y:20},{x:112,y:-5},{x:190,y:30},{x:215,y:85}], idx:[0,4] },
  { d:1.6,  path:[{x:262,y:300},{x:225,y:200},{x:150,y:150},{x:70,y:170},{x:30,y:120}], idx:[4,8] },
  { d:3.2,  path:[{x:-40,y:-20},{x:40,y:60},{x:120,y:110},{x:190,y:80},{x:212,y:130}], idx:[12,8] },
  { d:4.8,  path:[{x:270,y:-10},{x:180,y:60},{x:90,y:30},{x:20,y:90},{x:55,y:150}], idx:[20,10] },
  { d:6.4,  path:[{x:-46,y:290},{x:20,y:220},{x:110,y:250},{x:190,y:200},{x:215,y:150}], idx:[30,10] }
];

/* starfield */
const stars = [];
{
  const cols = ['#ffffff','#9bdfff','#fff0a0','#ffb0b0','#b0ffb0'];
  for (let i = 0; i < 70; i++)
    stars.push({ x:rnd(0,W), y:rnd(0,H), v:rnd(6,42), c:cols[irnd(0,4)], ph:rnd(0,6.3) });
}

/* ------------------------------- input -------------------------------- */
const keys = { l:false, r:false };
addEventListener('keydown', e => {
  initAudio();
  if ([' ', 'ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) e.preventDefault();
  if (e.repeat) return;
  switch (e.key){
    case 'ArrowLeft': case 'a': case 'A': keys.l = true; break;
    case 'ArrowRight': case 'd': case 'D': keys.r = true; break;
    case ' ': tryFire(); break;
    case 'Enter': onEnter(); break;
    case 'p': case 'P':
      if (game.mode === 'play' || game.mode === 'challenge') game.paused = !game.paused;
      break;
    case 'm': case 'M': toggleMute(); break;
  }
});
addEventListener('keyup', e => {
  switch (e.key){
    case 'ArrowLeft': case 'a': case 'A': keys.l = false; break;
    case 'ArrowRight': case 'd': case 'D': keys.r = false; break;
  }
});

function onEnter(){
  if (game.mode === 'attract') startGame();
  else if (game.mode === 'results') game.mode = 'attract';
}
function tryFire(){
  if (game.mode !== 'play' || !player.alive || game.paused) return;
  if (player.dual){
    if (pBullets.length === 0){
      pBullets.push({ x:player.x - 6, y:228 });
      pBullets.push({ x:player.x + 6, y:228 });
      game.shotsFired += 2; sfx('shot');
    }
  } else if (pBullets.length < 2){
    pBullets.push({ x:player.x, y:228 });
    game.shotsFired++; sfx('shot');
  }
}

/* ---------------------------- game flow ------------------------------- */
function addScore(p){
  game.score += p;
  if (game.score > game.hi){ game.hi = game.score; localStorage.setItem('galagaHi', String(game.hi)); }
  while (game.score >= game.nextExtra){
    game.nextExtra += 70000; player.lives++; sfx('extra');
  }
}
function startGame(){
  game.score = 0; game.stage = 1; game.nextExtra = 20000;
  game.shotsFired = 0; game.shotsHit = 0;
  player.lives = 2;
  beginStage();
}
function beginStage(){
  enemies = []; pBullets = []; eBullets = []; explosions = []; freedShips = [];
  game.breathMix = 0; game.diveTimer = 3;
  game.challenge = null; game.captureBoss = null;
  player.x = 112; player.dual = false; player.alive = true; player.invuln = 1.2;
  if (isChallenge(game.stage)){
    game.challenge = { wave:-1, waveTimer:0.5, spawned:0, hits:0, waves:[], bonus:0, done:false };
  } else {
    buildFormation();
  }
  game.mode = 'stageIntro'; game.timer = 2.0;
  sfx('jingle');
}
function isChallenge(s){ return s === 3 || (s - 3) % 4 === 0; }
function beginEntry(){
  for (const g of ENTRY)
    for (let i = g.idx[0]; i < g.idx[0] + g.idx[1]; i++){
      const e = enemies[i];
      e.state = 'wait';
      e.path = g.path;
      e.startTime = game.t + g.d + (i - g.idx[0]) * 0.16;
    }
  game.diveAllow = game.t + 2.5;
  game.mode = 'play';
}
/* standard 40-enemy formation: 4 boss / 16 goei / 20 zako */
function buildFormation(){
  const slot = (row, i, n) => ({ x:112 + (i - (n - 1) / 2) * (row < 1 ? 24 : 16), y:40 + row * 16 });
  let id = 0;
  for (let i = 0; i < 4; i++){ const p = slot(0, i, 4);   enemies.push(mkEnemy(id++, 'boss', p.x, p.y, 0)); }
  for (let r = 0; r < 2; r++) for (let i = 0; i < 8; i++){ const p = slot(1 + r, i, 8); enemies.push(mkEnemy(id++, 'goei', p.x, p.y, 1 + r)); }
  for (let r = 0; r < 2; r++) for (let i = 0; i < 10; i++){ const p = slot(3 + r, i, 10); enemies.push(mkEnemy(id++, 'zako', p.x, p.y, 3 + r)); }
}
function mkEnemy(id, type, bx, by, row){
  return { id, type, row, baseX:bx, baseY:by, x:bx, y:by, state:'wait',
           hp:type === 'boss' ? 2 : 1, u:0, path:null, from:null, k:0,
           divePath:null, retPath:null, beamT:0, beepT:0, captive:false,
           escortOf:null, shootT:rnd(0.5, 2.5) };
}
function slotPos(e){
  const cx = 112, cy = 72;
  const breath = 1 + Math.sin(game.t * 0.9) * 0.07 * game.breathMix;
  const swayAmp = 3 + 9 * (1 - game.breathMix);
  const sway = Math.sin(game.t * 0.45) * swayAmp;
  return { x: clamp(cx + (e.baseX - cx) * breath + sway, 12, 212),
           y: cy + (e.baseY - cy) * breath };
}

/* ------------------------- spawning / diving -------------------------- */
function startDive(){
  const form = enemies.filter(e => e.state === 'form');
  if (!form.length) return;
  const divers = enemies.filter(e => e.state === 'dive' || e.state === 'beam').length;
  if (divers >= Math.min(2 + Math.floor(game.stage / 2), 8)) return;
  const maxY = Math.max(...form.map(e => e.baseY));
  const cands = form.filter(e => e.baseY >= maxY - 16);      // bottom two rows first
  const e = (Math.random() < 0.75 && cands.length) ? cands[irnd(0, cands.length - 1)]
                                                   : form[irnd(0, form.length - 1)];
  launchDive(e);
}
function launchDive(e){
  const p0 = { x:e.x, y:e.y };
  if (e.type === 'boss' && !e.captive && game.stage >= 2 && Math.random() < 0.35){
    /* tractor-beam dive: boss stops mid-screen */
    const tx = clamp(player.x, 34, 190);
    e.divePath = [p0, { x:p0.x + rnd(-40, 40), y:p0.y + 40 }, { x:tx, y:80 }, { x:tx, y:112 }];
    e.state = 'dive'; e.u = 0; e.beamMode = true;
  } else {
    const side = rnd(-70, 70);
    e.divePath = [p0,
      { x:p0.x + rnd(-55, 55), y:p0.y + 30 },
      { x:player.x + side, y:180 },
      { x:player.x + rnd(-25, 25), y:320 }];
    e.state = 'dive'; e.u = 0; e.beamMode = false;
    e.shootT = Math.random() < 0.7 ? rnd(0.15, 0.5) : 99;
    if (e.type === 'boss' && game.stage >= 2 && Math.random() < 0.5){
      /* boss dive with 1-2 Goei escorts */
      const n = enemies.filter(o => o.type === 'goei' && o.state === 'form');
      const cnt = Math.min(irnd(1, 2), n.length);
      for (let i = 0; i < cnt; i++){
        const g = n[irnd(0, n.length - 1)];
        if (g.state !== 'form') continue;
        g.escortOf = e;
        const off = (i === 0 ? -20 : 20);
        g.divePath = [
          { x:g.x, y:g.y },
          { x:g.x + off * 0.5, y:g.y + 25 },
          { x:player.x + side + off, y:190 },
          { x:player.x + off, y:320 }];
        g.state = 'dive'; g.u = 0; g.beamMode = false; g.shootT = 99;
      }
    }
  }
}
function beginReturn(e){
  e.state = 'return'; e.u = 0;
  const s = slotPos(e);
  e.retPath = [{ x:clamp(rnd(20, 204), 20, 204), y:-18 },
               { x:s.x + rnd(-50, 50), y:rnd(30, 80) },
               { x:s.x, y:s.y }];
}
function fireAtPlayer(e, spd){
  const dx = player.x - e.x, dy = 236 - e.y, d = Math.hypot(dx, dy) || 1;
  eBullets.push({ x:e.x, y:e.y + 4, vx:dx / d * spd, vy:dy / d * spd });
}

/* --------------------------- combat helpers --------------------------- */
function boom(x, y, isPlayer){ explosions.push({ x, y, t:0, dur:isPlayer ? 0.6 : 0.4, p:!!isPlayer }); }
function addHit(){ game.shotsHit++; }
function killEnemy(e, bi){
  const idx = enemies.indexOf(e); if (idx < 0) return;
  enemies.splice(idx, 1);
  if (e.state === 'beam' && game.captureBoss === e) game.captureBoss = null;
  let pts = 0;
  const diving = !(e.state === 'form' || e.state === 'toSlot' || e.state === 'wait');
  if (game.mode === 'challenge'){
    pts = 100;
    if (game.challenge){ game.challenge.hits++; game.challenge.waves[e.wave]++; }
  } else if (e.type === 'zako') pts = diving ? 100 : 50;
  else if (e.type === 'goei')  pts = diving ? 160 : 80;
  else { /* boss */
    if (diving){
      const esc = enemies.filter(o => o.escortOf === e && o.state === 'dive').length;
      pts = 400 * (1 << esc);
    } else pts = 150;
  }
  addScore(pts);
  boom(e.x, e.y, false);
  sfx(e.type === 'boss' ? 'bossHit' : 'enemyDie');
  if (e.type === 'boss' && e.captive){
    if (diving){
      /* freed captive flies down and docks -> dual fighter */
      freedShips.push({ x:e.x, y:e.y - 14 });
    } else {
      /* killed in formation: captive is destroyed too */
      const s = slotPos(e);
      boom(s.x, s.y - 16, true);
    }
  }
  if (bi !== undefined) pBullets.splice(bi, 1);
}
function hitPlayerHalf(hx){
  if (player.dual){
    const side = hx < player.x ? -1 : 1;
    boom(player.x + side * 6, 236, true);
    player.dual = false;
    player.x -= side * 6;
    player.invuln = 1.0;
    sfx('playerDie');
  } else {
    boom(player.x, 236, true);
    sfx('playerDie');
    player.alive = false;
    if (player.lives > 0){
      player.lives--;
      game.mode = 'respawn'; game.timer = 1.8;
    } else {
      game.mode = 'gameover'; game.timer = 2.8;
    }
  }
}
function beginCapture(boss){
  game.mode = 'capture';
  game.captureBoss = boss;
  game.captureT = 0;
  game.captureFrom = { x:player.x, y:236 };
  boss.beamT = Math.max(boss.beamT, 2.0);
}
function completeCapture(){
  const boss = game.captureBoss;
  if (boss) boss.captive = true;
  game.captureBoss = null;
  if (player.dual){
    player.dual = false;               /* beam takes one of the two fighters */
    game.mode = 'play';
    player.invuln = 1.2;
  } else {
    player.alive = false;
    if (player.lives > 0){ player.lives--; game.mode = 'respawn'; game.timer = 1.8; }
    else { game.mode = 'gameover'; game.timer = 2.8; }
  }
}

/* ------------------------------ updating ------------------------------ */
function update(dt){
  game.t += dt;
  for (const s of stars){
    s.y += s.v * dt;
    if (s.y > H){ s.y = -1; s.x = rnd(0, W); }
  }
  if (game.paused) return;
  switch (game.mode){
    case 'attract': case 'results': break;
    case 'stageIntro':
      game.timer -= dt;
      if (game.timer <= 0){
        if (game.challenge){ game.mode = 'challenge'; game.challenge.waveTimer = 0.8; }
        else beginEntry();
      }
      break;
    case 'play':      updatePlay(dt); break;
    case 'challenge': updateChallenge(dt); break;
    case 'respawn':
      updateEnemies(dt); updateBullets(dt); updateFx(dt);
      game.timer -= dt;
      if (game.timer <= 0){
        player.alive = true; player.x = 112; player.invuln = 1.5;
        game.diveAllow = game.t + 1.2;
        game.mode = 'play';
      }
      break;
    case 'capture':
      game.captureT += dt / 1.1;
      updateEnemies(dt); updateBullets(dt); updateFx(dt);
      if (game.captureT >= 1) completeCapture();
      break;
    case 'stageClear':
      updateFx(dt);
      game.timer -= dt;
      if (game.timer <= 0){ game.stage++; beginStage(); }
      break;
    case 'challengeEnd':
      updateFx(dt);
      game.timer -= dt;
      if (game.timer <= 0){ game.stage++; beginStage(); }
      break;
    case 'gameover':
      updateEnemies(dt); updateBullets(dt); updateFx(dt);
      game.timer -= dt;
      if (game.timer <= 0) game.mode = 'results';
      break;
  }
}
function updatePlay(dt){
  /* player movement */
  if (player.alive){
    const sp = 140;
