    const e = enemies[i];
    switch (e.state){
      case 'wait':
        if (game.t >= e.startTime){
          if (game.mode === 'challenge'){ e.state = 'chal'; e.u = 0; }
          else { e.state = 'path'; e.u = 0; }
        }
        break;
      case 'path': {
        e.u += 0.30 * dt;
        const p = catmull(e.path, e.u);
        e.x = p.x; e.y = p.y;
        if (e.u >= 1){ e.state = 'toSlot'; e.from = { x:e.x, y:e.y }; e.k = 0; }
        /* entering enemies may fire */
        e.shootT -= dt;
        if (e.shootT <= 0){
          if (player.alive && e.y > 20 && e.y < 180 && Math.random() < 0.5) fireAtPlayer(e, bulletSpd);
          e.shootT = rnd(1.5, 3.5);
