        break; }
      case 'toSlot': {
        e.k = Math.min(1, e.k + dt * 2.2);
        const s = slotPos(e), k = e.k * e.k * (3 - 2 * e.k);
        e.x = e.from.x + (s.x - e.from.x) * k;
        e.y = e.from.y + (s.y - e.from.y) * k;
