        if (e.beamMode){
          if (e.u >= 1){ e.state = 'beam'; e.beamT = 2.8; e.beepT = 0; }
        } else {
          e.shootT -= dt;
          if (e.shootT <= 0 && player.alive && e.y > 30 && e.y < 210){
            fireAtPlayer(e, bulletSpd);
            e.shootT = rnd(0.4, 0.9);
