          /* captive held by a diving boss also fires */
          if (e.captive && player.alive && Math.random() < 0.005)
            eBullets.push({ x:e.x, y:e.y - 10, vx:rnd(-25, 25), vy:bulletSpd });
          if (e.y > 300 || e.u >= 1){ e.escortOf = null; beginReturn(e); }
