        }
        if (e.beamT <= 0){
          const s = slotPos(e);
          e.state = 'return'; e.u = 0;
          e.retPath = [{ x:e.x, y:e.y }, { x:(e.x + s.x) / 2, y:e.y - 50 }, { x:s.x, y:s.y }];
        }
        break; }
      case 'return': {
        e.u += 0.5 * dt;
        const p = catmull(e.retPath, e.u);
        e.x = p.x; e.y = p.y;
        e.shootT -= dt;
        if (e.shootT <= 0){
          if (player.alive && e.y > 10 && e.y < 170 && Math.random() < 0.4) fireAtPlayer(e, bulletSpd);
          e.shootT = rnd(1.2, 2.5);
        }
        if (e.u >= 1){ e.state = 'toSlot'; e.from = { x:e.x, y:e.y }; e.k = 0; }
