        e.x = (e.chal.fromLeft ? -20 : 244) + dir * t * 290;
        e.y = e.chal.by + Math.sin(t * Math.PI * 4) * 45;
        if (e.u >= 1){
          const w = e.wave;
          enemies.splice(i, 1);
          if (game.challenge && game.challenge.waves[w] < 8){ /* escaped */ }
