}
function updateBullets(dt){
  for (let i = pBullets.length - 1; i >= 0; i--){
    const b = pBullets[i]; b.y -= 340 * dt;
    if (b.y < -6) pBullets.splice(i, 1);
  }
  for (let i = eBullets.length - 1; i >= 0; i--){
    const b = eBullets[i];
    b.x += b.vx * dt; b.y += b.vy * dt;
    if (b.y > 282 || b.y < -6 || b.x < -6 || b.x > 230) eBullets.splice(i, 1);
  }
}
function updateFreed(dt){
  for (let i = freedShips.length - 1; i >= 0; i--){
    const f = freedShips[i];
    f.y += 70 * dt;
    if (f.y > 190 && player.alive) f.x += (player.x - f.x) * Math.min(1, dt * 6);
    if (f.y >= 228 && player.alive && !player.dual && Math.abs(f.x - player.x) < 8){
      player.dual = true; freedShips.splice(i, 1); sfx('dock');
