function playerBoxes(){
  if (!player.alive) return [];
  if (player.dual)
    return [{ x:player.x - 6, y:236, w:9, h:11 }, { x:player.x + 6, y:236, w:9, h:11 }];
  return [{ x:player.x, y:236, w:9, h:11 }];
}
function enemyBox(e){
