}
function collisions(){
  /* player bullets vs captives, then vs enemies */
  for (let i = pBullets.length - 1; i >= 0; i--){
    const b = pBullets[i];
    let hit = false;
    for (const e of enemies){
      if (e.type !== 'boss' || !e.captive) continue;
      const cx = e.x, cy = e.y - 16;
      if (overlap(b.x, b.y - 1, 1, 5, cx, cy, 9, 11)){
        boom(cx, cy, true); addScore(100); e.captive = false;
        addHit(); pBullets.splice(i, 1); hit = true; sfx('enemyDie'); break;
      }
    }
    if (hit) continue;
    for (const e of enemies){
      if (e.state === 'wait') continue;
      const eb = enemyBox(e);
      if (overlap(b.x, b.y - 1, 1, 5, eb.x, eb.y, eb.w, eb.h)){
        addHit();
        if (e.type === 'boss' && e.hp > 1){
          e.hp--; pBullets.splice(i, 1); sfx('bossHit');
        } else {
          killEnemy(e, i);
        }
        hit = true; break;
      }
    }
  }
