  const canBeHit = (game.mode === 'play' || game.mode === 'challenge') &&
                    player.alive && player.invuln <= 0;
  if (!canBeHit) return;
  const boxes = playerBoxes();
  /* enemy bullets vs player */
  for (let i = eBullets.length - 1; i >= 0; i--){
    const b = eBullets[i];
    for (const bx of boxes){
      if (overlap(b.x, b.y, 2, 4, bx.x, bx.y, bx.w, bx.h)){
        eBullets.splice(i, 1); hitPlayerHalf(b.x); return;
      }
    }
  }
