  for (const e of enemies){
    if (e.state === 'wait' || e.state === 'form' || e.state === 'toSlot') continue;
    const eb = enemyBox(e);
    for (const bx of boxes){
      if (overlap(eb.x, eb.y, eb.w, eb.h, bx.x, bx.y, bx.w, bx.h)){
        killEnemy(e);
        hitPlayerHalf(e.x);
